css:
@import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600&family=Saira+Condensed:wght@600;700;800&display=swap');

/* =====================================================================
   TCADMIN — Total Control · base layer (tokens + typography + primitives)
   Mirrors www.tcadmin.com (src/styles/global.css in TCAdminV3-Website).
   FULL-TRUST theme: @import / @keyframes / @media / clip-path render raw.
   Sandboxed it degrades to system fonts and no motion, nothing breaks.

   Colors come from the live MudBlazor palette wherever the palette has
   the role, so editing the theme's palette re-skins the template too.
   The few site tokens MudBlazor has no slot for are set per mode below.
   ===================================================================== */
:root {
    --tca-bg: var(--mud-palette-background);
    --tca-bg-deep: var(--mud-palette-background-gray);
    --tca-surface: var(--mud-palette-surface);
    --tca-line: var(--mud-palette-lines-default);
    --tca-line-soft: var(--mud-palette-divider);
    --tca-text: var(--mud-palette-text-primary);
    --tca-text-dim: var(--mud-palette-text-secondary);
    --tca-accent: var(--mud-palette-primary);
    --tca-accent-rgb: var(--mud-palette-primary-rgb);
    --tca-accent-hot: var(--mud-palette-secondary);
    --tca-accent-ink: var(--mud-palette-primary-text);
    --tca-online: var(--mud-palette-success);
    --tca-offline: var(--mud-palette-error);
    --tca-starting: var(--mud-palette-warning);

    /* Dark (the site's default look). */
    --tca-surface-2: #0d2a4f;
    --tca-text-faint: #7189aa;
    --tca-brand: #004b82;
    --tca-chrome: #020916;
    --tca-grid-line: rgb(120 170 230 / 0.045);
    --tca-grid-lit: rgb(1 165 223 / 0.55);
    --tca-glow-text: 0 0 48px color-mix(in srgb, var(--tca-accent) 28%, transparent);
    --tca-shadow-pop: 0 24px 50px -20px rgb(0 0 0 / 0.7);
    --tca-shadow-card: 0 1px 0 rgb(255 255 255 / 0.03) inset;
    /* Black stock logos (/img/logos/tcadmin.png) → white on navy. */
    --tca-logo-tint: brightness(0) invert(1);
    /* Input wells, tooltips, translucent chrome (header/footer bars). */
    --tca-well: color-mix(in srgb, var(--tca-bg-deep) 55%, transparent);
    --tca-tip-bg: var(--tca-chrome);
    --tca-tip-fg: var(--tca-text);
    --tca-tip-line: var(--tca-line);
    --tca-bar-bg: color-mix(in srgb, var(--tca-bg) 88%, transparent);
    --tca-scroll: #1f4372;
    /* Backdrop glow strengths (accent top-left, brand navy top-right) — per mode,
       because 45% navy over the light page reads as a grey smudge. */
    --tca-glow-accent: 13%;
    --tca-glow-brand: 45%;

    --tca-font-display: 'Saira Condensed', 'Arial Narrow', sans-serif;
    --tca-font-body: 'IBM Plex Sans', system-ui, -apple-system, 'Segoe UI', sans-serif;
    --tca-font-mono: 'JetBrains Mono', ui-monospace, 'Cascadia Mono', Consolas, monospace;

    --tca-r: 3px;
    --tca-cut-sm: 7px;
    --tca-cut: 10px;
    --tca-cut-lg: 14px;
    --tca-ease: cubic-bezier(0.2, 0.7, 0.2, 1);
    --tca-fast: 0.15s;

    /* MudBlazor typography → the site's type system. */
    --mud-typography-default-family: var(--tca-font-body);
    --mud-typography-body1-family: var(--tca-font-body);
    --mud-typography-body2-family: var(--tca-font-body);
    --mud-typography-subtitle1-family: var(--tca-font-body);
    --mud-typography-subtitle2-family: var(--tca-font-body);
    --mud-typography-caption-family: var(--tca-font-body);
    --mud-typography-overline-family: var(--tca-font-mono);
    --mud-typography-button-family: var(--tca-font-display);
    --mud-typography-h1-family: var(--tca-font-display);
    --mud-typography-h2-family: var(--tca-font-display);
    --mud-typography-h3-family: var(--tca-font-display);
    --mud-typography-h4-family: var(--tca-font-display);
    --mud-typography-h5-family: var(--tca-font-display);
    --mud-typography-h6-family: var(--tca-font-display);
}

/* Light mode: same family, cyan deepens to TCAdmin blue for AA on white (site: [data-theme=light]).
   MudLayout carries .light-mode/.dark-mode; popovers + dialogs render outside it, hence :root:has(). */
:root:has(.mud-layout.light-mode) {
    --tca-surface-2: #eaf0f8;
    --tca-text-faint: #5a6d89;
    --tca-chrome: #e3eaf3;
    --tca-grid-line: rgb(0 75 130 / 0.06);
    --tca-grid-lit: rgb(0 114 176 / 0.35);
    --tca-glow-text: none;
    --tca-shadow-pop: 0 24px 50px -24px rgb(10 26 48 / 0.35);
    --tca-shadow-card: 0 1px 2px rgb(10 26 48 / 0.04);
    /* Black stock logo → TCAdmin navy #004b82 (canvas-verified: renders exactly 0,75,130). */
    --tca-logo-tint: brightness(0) saturate(100%) invert(19%) sepia(63%) saturate(2647%) hue-rotate(187deg) brightness(90%) contrast(101%);
    --tca-well: color-mix(in srgb, var(--tca-bg-deep) 45%, var(--tca-surface));
    --tca-tip-bg: #0a1a30;
    --tca-tip-fg: #eaf1fa;
    --tca-tip-line: transparent;
    --tca-bar-bg: color-mix(in srgb, var(--tca-bg) 90%, transparent);
    --tca-scroll: #b4c3d8;
    --tca-glow-accent: 9%;
    --tca-glow-brand: 10%;
}

html { -webkit-font-smoothing: antialiased; text-rendering: optimizeLegibility; }
body { font-family: var(--tca-font-body); }
::selection { background: color-mix(in srgb, var(--tca-accent) 35%, transparent); }
:focus-visible { outline: 2px solid var(--tca-accent); outline-offset: 2px; }

/* ---------------------------------------------------------------------
   Shared primitives (prefix .tcs-). Surfaces compose these.
   --------------------------------------------------------------------- */

/* Display type: condensed, bold, uppercase — the site's headline voice. */
.tcs-display {
    font-family: var(--tca-font-display);
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.005em;
    line-height: 0.92;
}
.tcs-mono {
    font-family: var(--tca-font-mono);
    font-size: 0.6875rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

/* HUD cut corners (top-left + bottom-right), with the border redrawn across each cut.
   Needs ::before/::after free — never put it on .mud-ripple elements (Mud's ripple uses ::after). */
.tcs-cut {
    --cut: var(--tca-cut-lg);
    --cut-line: var(--tca-line-soft);
    position: relative;
    clip-path: polygon(var(--cut) 0, 100% 0, 100% calc(100% - var(--cut)), calc(100% - var(--cut)) 100%, 0 100%, 0 var(--cut));
}
.tcs-cut::before, .tcs-cut::after {
    content: ''; position: absolute; z-index: 3; pointer-events: none;
    width: var(--cut); height: var(--cut);
    background: linear-gradient(to bottom right, transparent calc(50% - 0.8px), var(--cut-line) calc(50% - 0.8px), var(--cut-line) calc(50% + 0.8px), transparent calc(50% + 0.8px));
}
.tcs-cut::before { top: -1px; left: -1px; }
.tcs-cut::after { bottom: -1px; right: -1px; }

/* Version / "new" tag (site .tag-v3). */
.tcs-tag {
    display: inline-flex; align-items: center; gap: 6px;
    font-family: var(--tca-font-display); font-weight: 700; font-size: 0.8125rem; letter-spacing: 0.04em; line-height: 1.5;
    color: var(--tca-accent); border: 1px solid color-mix(in srgb, var(--tca-accent) 45%, transparent);
    padding: 1px 7px; border-radius: var(--tca-r); white-space: nowrap;
}

/* Status dots — green / red / amber are reserved for service state, as on the site. */
.tcs-dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; flex: none; background: var(--tca-text-faint); }
.tcs-dot--online { background: var(--tca-online); box-shadow: 0 0 8px color-mix(in srgb, var(--tca-online) 70%, transparent); }
.tcs-dot--offline { background: var(--tca-offline); }
.tcs-dot--starting { background: var(--tca-starting); }

/* Logo mark: the stock black PNG tinted per mode. */
.tcs-logo { filter: var(--tca-logo-tint); }

/* The fixed blueprint grid + brand glows behind everything (site BackgroundFx + .page-head). */
.tcs-backdrop {
    background-color: var(--tca-bg);
    background-image:
        radial-gradient(40% 55% at 4% 0%, color-mix(in srgb, var(--tca-accent) var(--tca-glow-accent), transparent), transparent 70%),
        radial-gradient(35% 50% at 92% 0%, color-mix(in srgb, var(--tca-brand) var(--tca-glow-brand), transparent), transparent 70%),
        linear-gradient(to right, var(--tca-grid-line) 1px, transparent 1px),
        linear-gradient(to bottom, var(--tca-grid-line) 1px, transparent 1px);
    background-size: auto, auto, 64px 64px, 64px 64px;
    background-position: 0 0, 0 0, center top, center top;
    background-repeat: no-repeat, no-repeat, repeat, repeat;
    background-attachment: fixed;
}

@keyframes tcs-rise { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
@keyframes tcs-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes tcs-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.45; } }
@keyframes tcs-scan { from { transform: translateX(-110%); } to { transform: translateX(260%); } }
@keyframes tcs-spin { to { transform: rotate(360deg); } }

@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
}


/* =====================================================================
   TCADMIN — Total Control · global MudBlazor component skin
   Applies everywhere: shell pages, login, dialogs, popovers. Chrome-only
   rules live in Shell.css. Colors resolve through the --tca-* tokens
   (which mostly read the live Mud palette), so palette edits still win.

   SPECIFICITY CONTRACT: every rule here is at most as specific as the Mud
   rule it replaces (usually one class), with qualifiers wrapped in :where().
   Template CSS is injected after MudBlazor.min.css, so ties go to us — and
   any surface (login, service pages) overrides the skin with a plain class.
   The few rules that must out-rank a multi-class Mud rule say so inline.

   Corner-kit knobs (custom properties, set per element):
     --tca-cutk  cut size (default per component: --tca-cut-sm / --tca-cut / --tca-cut-lg)
     --tca-edge  colour of the edge redrawn across each cut (swap it on :hover / :focus)
   ===================================================================== */

/* ---------------------------------------------------------------------
   Type scale — Saira Condensed for display roles, Plex for reading.
   Mud reads these vars on :root; template CSS is injected after
   MudThemeProvider's <style>, so ours win at equal specificity.
   --------------------------------------------------------------------- */
:root {
    --mud-typography-button-size: 0.9375rem;
    --mud-typography-button-weight: 700;
    --mud-typography-button-letterspacing: 0.06em;
    --mud-typography-button-text-transform: uppercase;
    --mud-typography-button-lineheight: 1.6;
    --mud-typography-h4-weight: 800;
    --mud-typography-h5-weight: 800;
    --mud-typography-h6-weight: 700;
    --mud-typography-overline-size: 0.6875rem;
    --mud-typography-overline-letterspacing: 0.12em;
}
.mud-typography-h1, .mud-typography-h2, .mud-typography-h3, .mud-typography-h4, .mud-typography-h5 {
    text-transform: uppercase;
    letter-spacing: 0.01em;
    line-height: 1.02;
}
.mud-typography-h6 { letter-spacing: 0.01em; line-height: 1.2; }
.mud-typography-overline { font-weight: 500; color: var(--tca-text-faint); }
a { text-underline-offset: 3px; }

/* ---------------------------------------------------------------------
   Corner kit — the site's HUD cut (top-left + bottom-right) with the
   1px edge redrawn across each cut. Background layers, not ::before/
   ::after: Mud's ripple owns ::after on buttons, and papers/inputs then
   need no position change. Grouped / toggle buttons are excluded — a cut
   between siblings reads as a gap (the toggle GROUP is cut instead).
   --------------------------------------------------------------------- */
.mud-button-outlined:where(.mud-button-root:not(.mud-button-group-root *, .mud-toggle-item)),
.mud-input-outlined:where(.mud-input),
.mud-toggle-group-outlined:where(.mud-toggle-group),
.mud-dialog,
.tcs-kit {
    --tca-corner: linear-gradient(to bottom right, transparent calc(50% - 0.8px), var(--tca-edge) calc(50% - 0.8px), var(--tca-edge) calc(50% + 0.8px), transparent calc(50% + 0.8px));
    clip-path: polygon(var(--tca-cutk) 0, 100% 0, 100% calc(100% - var(--tca-cutk)), calc(100% - var(--tca-cutk)) 100%, 0 100%, 0 var(--tca-cutk));
    background-image: var(--tca-corner), var(--tca-corner);
    background-size: var(--tca-cutk) var(--tca-cutk);
    background-position: 0 0, 100% 100%;
    background-repeat: no-repeat;
    background-origin: border-box;
}
.tcs-kit { --tca-cutk: var(--tca-cut-lg); --tca-edge: var(--tca-line-soft); }

/* ---------------------------------------------------------------------
   Buttons — Saira 700 uppercase (via the type vars), cut corners on
   filled + outlined, a light sweep across the primary CTA on hover.
   --------------------------------------------------------------------- */
.mud-button { border-radius: var(--tca-r); }
.mud-button-filled:where(.mud-button-root:not(.mud-button-group-root *, .mud-toggle-item)),
.mud-button-outlined:where(.mud-button-root:not(.mud-button-group-root *, .mud-toggle-item)) {
    --tca-cutk: var(--tca-cut);
    border-radius: 0;
    clip-path: polygon(var(--tca-cutk) 0, 100% 0, 100% calc(100% - var(--tca-cutk)), calc(100% - var(--tca-cutk)) 100%, 0 100%, 0 var(--tca-cutk));
}
.mud-button-filled-size-small, .mud-button-outlined-size-small,
.mud-icon-button:where(.mud-button-filled, .mud-button-outlined) { --tca-cutk: var(--tca-cut-sm); }

.mud-button-filled { box-shadow: none; transition: background-color var(--tca-fast), color var(--tca-fast), transform 0.1s; }
.mud-button-filled:where(:active) { transform: translateY(1px); }
.mud-button-filled-primary { isolation: isolate; overflow: hidden; }
/* Equal to Mud's own .mud-button-filled.mud-button-filled-primary:hover (darken) — accent-hot instead. */
.mud-button-filled.mud-button-filled-primary:hover:where(:not(:disabled)) { background-color: var(--tca-accent-hot); }
.mud-button-filled-primary::before {
    content: ''; position: absolute; inset: 0; z-index: -1; pointer-events: none;
    background: linear-gradient(105deg, transparent 35%, rgb(255 255 255 / 0.4) 50%, transparent 65%);
    transform: translateX(-120%);
}
@media (prefers-reduced-motion: no-preference) {
    .mud-button-filled-primary:where(:hover)::before { transform: translateX(120%); transition: transform 0.6s ease; }
}

/* Outlined = the site's ghost button: surface tint, line edge, accent on hover.
   Coloured outlines keep their hue but sit half-mixed into the line colour. */
.mud-button-outlined:where(.mud-button-root:not(.mud-button-group-root *, .mud-toggle-item)) {
    --tca-edge: color-mix(in srgb, currentColor 55%, var(--tca-line));
    border-color: var(--tca-edge);
    background-color: color-mix(in srgb, var(--tca-surface) 60%, transparent);
    transition: background-color var(--tca-fast), border-color var(--tca-fast), color var(--tca-fast);
}
.mud-button-outlined-default:where(.mud-button-root:not(.mud-button-group-root *, .mud-toggle-item)) { --tca-edge: var(--tca-line); color: var(--tca-text); }
.mud-button-outlined:where(:not(:disabled):hover) { --tca-edge: currentColor; }
.mud-button-outlined-default:where(:not(:disabled):hover) { --tca-edge: var(--tca-accent); }
.mud-button-outlined:where(:disabled) { --tca-edge: var(--tca-line-soft); }

/* Toggle groups: the GROUP is the cut plate; items stay square inside it and
   take the group's edge for their delimiters (Mud: border-color: inherit). */
.mud-toggle-group-outlined:where(.mud-toggle-group) {
    --tca-cutk: var(--tca-cut);
    --tca-edge: var(--tca-line);
    border-color: var(--tca-edge);
    border-radius: 0;
}
/* Equal to Mud's .mud-toggle-group-outlined.mud-toggle-group-primary border rule. */
.mud-toggle-group-outlined.mud-toggle-group-primary { --tca-edge: color-mix(in srgb, var(--tca-accent) 55%, var(--tca-line)); border-color: var(--tca-edge); }

/* Keyboard focus: an outside outline would be cut away by the clip-path, so draw it inside.
   Filled buttons ring in their own text colour (contrasts with any fill). */
.mud-button-filled:focus-visible { outline: 2px solid currentColor; outline-offset: -4px; }
.mud-button-outlined:focus-visible { outline: 2px solid var(--tca-accent); outline-offset: -4px; }

/* Icon buttons: square HUD hit-area instead of Material's circle
   (switch/radio bases keep theirs — the thumb/dot is round by design). */
.mud-icon-button:where(:not(.mud-switch-base, .mud-radio *)) { border-radius: var(--tca-r); }
.mud-icon-button:where(.mud-button-filled, .mud-button-outlined) { border-radius: 0; }

/* ---------------------------------------------------------------------
   Inputs — outlined fields become recessed wells with cut corners.
   Mud colours the fieldset edge (lines-inputs → action-default on hover →
   primary on focus → error); --tca-edge mirrors those states so the
   redrawn cut edges always match. Zeroing Mud's radius VARIABLE locally
   squares the fieldset without out-ranking its 3-class rule.
   --------------------------------------------------------------------- */
.mud-input-outlined:where(.mud-input) {
    --tca-cutk: var(--tca-cut-sm);
    --tca-edge: var(--mud-palette-lines-inputs);
    --mud-default-borderradius: 0;
    background-color: var(--tca-well);
}
.mud-input-outlined:where(.mud-input:not(.mud-disabled):not(:focus-within):hover) { --tca-edge: var(--mud-palette-action-default); }
.mud-input-outlined:where(.mud-input:focus-within) { --tca-edge: var(--mud-palette-primary); }
.mud-input-outlined:where(.mud-input.mud-disabled) { --tca-edge: var(--mud-palette-action-disabled); background-color: transparent; }
.mud-input-outlined:where(.mud-input-error *, .mud-input.mud-input-error) { --tca-edge: var(--mud-palette-error); }
/* Mud signals focus with the 2px accent edge — the global focus ring would be clipped by the cut. */
.mud-input-slot:focus-visible, .mud-input-root:focus-visible { outline: none; }
/* Dense data-grid editors and pagination selects stay flat. */
.mud-input-outlined:where(.mud-table-pagination *, .mud-data-grid .edit-mode-cell *) { background-color: transparent; clip-path: none; background-image: none; }

.mud-input-label { color: var(--tca-text-dim); }
.mud-input-label-outlined { font-weight: 500; }
.mud-input-helper-text { color: var(--tca-text-faint); font-size: 0.75rem; }
/* Equal to Mud's placeholder rules (which fade currentColor to 42%). */
.mud-input > input.mud-input-root::placeholder, .mud-input > textarea.mud-input-root::placeholder { color: var(--tca-text-faint); opacity: 1; }
.mud-input-adornment .mud-icon-root { color: var(--tca-text-faint); }
.mud-input-adornment-start .mud-icon-root:where(.mud-input:focus-within *) { color: var(--tca-accent); }

/* ---------------------------------------------------------------------
   Popovers, menus, select lists — opaque surface + line ring.
   Ring = inset OUTLINE, never border/padding: MudSelect gives the popover
   and its inner list the same max-height, so a border adds a 2nd scrollbar.
   Tooltips are .mud-popover too — they get their own plate below.
   --------------------------------------------------------------------- */
.mud-popover:where(:not(.mud-tooltip)) {
    background-color: var(--tca-surface);
    outline: 1px solid var(--tca-line);
    outline-offset: -1px;
    border-radius: var(--tca-r);
    box-shadow: var(--tca-shadow-pop);
}
.mud-list:where(.mud-popover *) { padding-top: 4px; padding-bottom: 4px; }
.mud-list-item-clickable:hover, .mud-menu-item:hover { background-color: color-mix(in srgb, var(--tca-accent) 12%, var(--tca-surface-2)); }
.mud-selected-item, .mud-selected-item:hover {
    color: var(--tca-accent);
    background-color: color-mix(in srgb, var(--tca-accent) 10%, transparent);
    box-shadow: inset 2px 0 0 var(--tca-accent);
}
.mud-menu-item-text, .mud-list-item-text { font-size: 0.9375rem; }

/* ---------------------------------------------------------------------
   Tooltips — compact, high-contrast plate (dark chrome in dark mode,
   ink in light mode, tokens in _base.css). Equal to Mud's 2-class rules.
   --------------------------------------------------------------------- */
.mud-tooltip.mud-tooltip-default {
    color: var(--tca-tip-fg);
    background-color: var(--tca-tip-bg);
    box-shadow: 0 0 0 1px var(--tca-tip-line), 0 10px 24px -12px rgb(0 0 0 / 0.6);
    font-family: var(--tca-font-body);
    font-weight: 500;
    font-size: 0.75rem;
    letter-spacing: 0.01em;
    border-radius: var(--tca-r);
}
.mud-tooltip.mud-tooltip-default.mud-tooltip-arrow::after { border-color: var(--tca-tip-bg) transparent transparent transparent; }

/* ---------------------------------------------------------------------
   Tabs — condensed uppercase labels, 1px base line, glowing 2px slider.
   Only the default (uncoloured) tab bar: a Color=Primary bar keeps Mud's
   filled look and its contrast-text labels.
   --------------------------------------------------------------------- */
.mud-tabs-tabbar:where(:not(.mud-tabs-tabbar-primary, .mud-tabs-tabbar-secondary, .mud-tabs-tabbar-tertiary, .mud-tabs-tabbar-info, .mud-tabs-tabbar-success, .mud-tabs-tabbar-warning, .mud-tabs-tabbar-error, .mud-tabs-tabbar-dark)) {
    background-color: transparent;
    box-shadow: inset 0 -1px 0 var(--tca-line-soft);
}
.mud-tab {
    font-family: var(--tca-font-display);
    font-weight: 700;
    font-size: 0.9375rem;
    letter-spacing: 0.06em;
    min-height: 46px;
    transition: color var(--tca-fast), background-color var(--tca-fast);
}
.mud-tab:where(.mud-tabs-tabbar:not(.mud-tabs-tabbar-primary, .mud-tabs-tabbar-secondary, .mud-tabs-tabbar-tertiary, .mud-tabs-tabbar-info, .mud-tabs-tabbar-success, .mud-tabs-tabbar-warning, .mud-tabs-tabbar-error, .mud-tabs-tabbar-dark) *) { color: var(--tca-text-dim); }
.mud-tab:where(:hover) { color: var(--tca-text); background-color: color-mix(in srgb, var(--tca-accent) 5%, transparent); }
.mud-tab.mud-tab-active { color: var(--tca-accent); }
.mud-tab.mud-tab-active:hover { background-color: color-mix(in srgb, var(--tca-accent) 8%, transparent); }
.mud-tab-slider-horizontal { box-shadow: 0 0 10px color-mix(in srgb, var(--tca-accent) 60%, transparent); }
.mud-icon-button:where(.mud-tabs-scroll-button *) { color: var(--tca-text-dim); }

/* ---------------------------------------------------------------------
   Chips — squared tags in the display face (site .tag-v3 voice).
   The size rules match Mud's .mud-chip.mud-chip-size-* (which set the
   pill radius), so a single-class surface rule can't reach the radius.
   --------------------------------------------------------------------- */
.mud-chip { font-family: var(--tca-font-display); font-weight: 600; letter-spacing: 0.04em; }
.mud-chip:is(.mud-chip-size-small, .mud-chip-size-medium, .mud-chip-size-large) { border-radius: var(--tca-r); }
.mud-chip.mud-chip-size-small { font-size: 0.8125rem; }
.mud-chip.mud-chip-size-medium { font-size: 0.9375rem; }
.mud-chip-filled.mud-chip-color-default {
    background-color: var(--tca-surface-2);
    color: var(--tca-text-dim);
    box-shadow: inset 0 0 0 1px var(--tca-line);
}
.mud-chip-outlined { border-color: var(--tca-line); }

/* ---------------------------------------------------------------------
   Data tables / grids — mono uppercase column heads on a sunken band,
   1px soft row lines, accent wash on hover.
   --------------------------------------------------------------------- */
/* Equal to Mud's .mud-table-root .mud-table-head .mud-table-cell (it sets the head typography). */
.mud-table-root .mud-table-head .mud-table-cell {
    font-family: var(--tca-font-mono);
    font-size: 0.6875rem;
    font-weight: 600;
    letter-spacing: 0.09em;
    text-transform: uppercase;
    color: var(--tca-text-dim);
    /* Opaque (not a translucent band) so sticky header cells hide what scrolls under them. */
    background-color: color-mix(in srgb, var(--tca-bg-deep) 45%, var(--tca-surface));
    border-bottom-color: var(--tca-line);
}
/* Sticky columns: Mud paints them background-gray (a near-black slab in dark) — use the plate
   colour plus a hairline on the inner edge. Equal to Mud's .mud-data-grid .mud-table-cell.sticky-*. */
.mud-data-grid .mud-table-cell.sticky-right { background-color: var(--tca-surface); box-shadow: inset 1px 0 0 var(--tca-line-soft); }
.mud-data-grid .mud-table-cell.sticky-left { background-color: var(--tca-surface); box-shadow: inset -1px 0 0 var(--tca-line-soft); }
.mud-table-root .mud-table-head .mud-table-cell:is(.sticky-right, .sticky-left) { background-color: color-mix(in srgb, var(--tca-bg-deep) 45%, var(--tca-surface)); }
.mud-table-row:hover > .mud-table-cell:is(.sticky-right, .sticky-left):where(.mud-table-hover .mud-table-body *) { background-color: color-mix(in srgb, var(--tca-accent) 6%, var(--tca-surface)); }
.mud-button-root:where(.mud-table-head *) { color: var(--tca-text-faint); }
.mud-table-sort-label-icon.mud-direction-asc, .mud-table-sort-label-icon.mud-direction-desc { color: var(--tca-accent); }
.mud-table-cell { border-bottom-color: var(--tca-line-soft); }
.mud-table-pagination-caption { color: var(--tca-text-dim); }
.mud-table-pagination-caption:last-of-type { font-family: var(--tca-font-mono); font-size: 0.75rem; letter-spacing: 0.04em; }
.mud-table-pagination-toolbar { border-top: 1px solid var(--tca-line-soft); }

/* ---------------------------------------------------------------------
   Cards / panels — dividers in the soft line.
   (Plating of top-level content cards lives in Shell.css: dialogs and
   popovers are papers too and must keep their own surfaces.)
   --------------------------------------------------------------------- */
.mud-divider { border-color: var(--tca-line-soft); }
.mud-paper-outlined { border-color: var(--tca-line-soft); }

/* ---------------------------------------------------------------------
   Dialogs — cut-corner plate, accent top edge, condensed title, sunken
   action bar. Overlay gets a light blur behind the dim.
   --------------------------------------------------------------------- */
.mud-dialog {
    --tca-cutk: var(--tca-cut-lg);
    --tca-edge: var(--tca-line);
    background-color: var(--tca-surface);
    /* 3rd layer = the top edge itself (border-top is transparent so it shows): line → accent → line. */
    background-image: var(--tca-corner), var(--tca-corner), linear-gradient(90deg, var(--tca-line), var(--tca-accent) 50%, var(--tca-line));
    background-size: var(--tca-cutk) var(--tca-cutk), var(--tca-cutk) var(--tca-cutk), 100% 1px;
    background-position: 0 0, 100% 100%, 0 0;
    border: 1px solid var(--tca-line);
    border-top-color: transparent;
    border-radius: 0;
    box-shadow: none;
}
/* Equal to Mud's .mud-dialog .mud-dialog-* rules. */
.mud-dialog .mud-dialog-title { padding: 18px 24px 14px; border-bottom: 1px solid var(--tca-line-soft); }
.mud-dialog-title .mud-typography-h6 { font-weight: 800; font-size: 1.375rem; text-transform: uppercase; letter-spacing: 0.01em; line-height: 1.1; }
.mud-dialog .mud-dialog-content { padding-top: 16px; }
.mud-dialog .mud-dialog-actions {
    padding: 12px 16px;
    gap: 10px;
    border-top: 1px solid var(--tca-line-soft);
    background-color: color-mix(in srgb, var(--tca-bg-deep) 35%, transparent);
}
.mud-overlay-dark:where(.mud-dialog-container *) { backdrop-filter: blur(3px); }

/* ---------------------------------------------------------------------
   Alerts — squared, with a 2px severity rail on the tinted variants.
   --------------------------------------------------------------------- */
.mud-alert { border-radius: var(--tca-r); }
.mud-alert:where([class*='mud-alert-text-']) { box-shadow: inset 2px 0 0 currentColor; }

/* ---------------------------------------------------------------------
   Snackbars — dark HUD toasts: surface plate, line ring, severity rail +
   icon. Overrides Mud's filled colours so every toast reads as one family.
   --------------------------------------------------------------------- */
.mud-snackbar {
    --tca-sev: var(--tca-accent);
    color: var(--tca-text);
    background-color: var(--tca-surface);
    border-radius: var(--tca-r);
    box-shadow: inset 3px 0 0 var(--tca-sev), inset 0 0 0 1px var(--tca-line), var(--tca-shadow-pop);
    font-family: var(--tca-font-body);
    font-weight: 500;
    padding-left: 18px;
}
.mud-snackbar:where(.mud-alert-filled-success, .mud-alert-text-success, .mud-alert-outlined-success) { --tca-sev: var(--tca-online); }
.mud-snackbar:where(.mud-alert-filled-error, .mud-alert-text-error, .mud-alert-outlined-error) { --tca-sev: var(--tca-offline); }
.mud-snackbar:where(.mud-alert-filled-warning, .mud-alert-text-warning, .mud-alert-outlined-warning) { --tca-sev: var(--tca-starting); }
.mud-snackbar-icon { color: var(--tca-sev); }
.mud-button-root:where(.mud-snackbar-content-action *) { color: var(--tca-text-dim); }

/* ---------------------------------------------------------------------
   Progress — accent bar with a soft glow on a faint accent track.
   (Equal to Mud's .mud-progress-linear.mud-progress-linear-color-primary rules.)
   --------------------------------------------------------------------- */
.mud-progress-linear { border-radius: 0; }
.mud-progress-linear.mud-progress-linear-color-primary:not(.mud-progress-linear-buffer) { background-color: color-mix(in srgb, var(--tca-accent) 16%, transparent); }
.mud-progress-linear.mud-progress-linear-color-primary .mud-progress-linear-bar { background-color: var(--tca-accent); box-shadow: 0 0 10px color-mix(in srgb, var(--tca-accent) 55%, transparent); }

/* ---------------------------------------------------------------------
   Switches + checkboxes — squared HUD toggle: 3px track, 2px knob.
   (Equal to Mud's switch rules; the disabled one must match its !important.)
   --------------------------------------------------------------------- */
.mud-switch-span .mud-switch-track { border-radius: var(--tca-r); opacity: 1; background-color: var(--tca-line); }
.mud-switch-base.mud-checked + .mud-switch-track { opacity: 0.55; }
.mud-switch-base.mud-switch-disabled + .mud-switch-track { opacity: 0.35 !important; }
.mud-switch-button [class*='mud-switch-thumb-'] { border-radius: 2px; box-shadow: 0 1px 2px rgb(0 0 0 / 0.35); }
.mud-switch-button [class*='mud-switch-thumb-']:where(.mud-switch-base:not(.mud-checked) *) { background-color: var(--tca-text-dim); }
.mud-checkbox .mud-icon-root, .mud-radio .mud-icon-root { transition: color var(--tca-fast); }

/* ---------------------------------------------------------------------
   Scrollbars — thin, line-coloured thumb (scrollbar-color is inherited,
   so one declaration on :root covers every scroller).
   --------------------------------------------------------------------- */
:root { scrollbar-color: var(--tca-scroll) transparent; }
* { scrollbar-width: thin; }

contents.content:
{% comment %}
  TCADMIN — Total Control · DockerService.Header
  Same hero band as the game header (shared CSS), re-cut for a container: image:tag in the meta
  line, the copyable host (service-host-address) + the published ports in the chip strip. Docker
  blueprints carry no art, so the band shows the blueprint grid + glow alone unless one is set.
{% endcomment %}
<header class="tcs-svh tcs-svh--docker">
  {% if Service.ImageUrl %}<img class="tcs-svh__art" src="{{ Service.ImageUrl }}" alt="" aria-hidden="true">{% endif %}
  {% unless Service.ImageUrl %}<span class="tcs-svh__mark" aria-hidden="true">{% component "service-icon" %}</span>{% endunless %}
  <span class="tcs-svh__rail" aria-hidden="true"></span>
  <div class="tcs-svh__main">
    <div class="tcs-svh__id">
      <span class="tcs-svh__icon">{% component "service-icon" %}</span>
      <div class="tcs-svh__stack">
        <div class="tcs-svh__kicker">
          <span class="tcs-svh__state">{% component "live-status-orb" %}{% component "live-status" %}</span>
          <span class="tcs-svh__meta">
            <span class="tcs-svh__bp">{{ Service.BlueprintShortName | default: Service.BlueprintName }}</span>
            {% if Service.DatacenterName %}<span class="tcs-svh__loc"><i class="fa-solid fa-location-dot" aria-hidden="true"></i>{{ Service.DatacenterName }}</span>{% elsif Service.ServerName %}<span class="tcs-svh__loc"><i class="fa-solid fa-server" aria-hidden="true"></i>{{ Service.ServerName }}</span>{% endif %}
          </span>
        </div>
        <h1 class="tcs-svh__name">{% component "live-name" %}</h1>
      </div>
    </div>
    {% if Permissions.Control %}
    <div class="tcs-svh__power">
      {% component "power-start" %}
      {% component "power-restart" %}
      {% component "power-stop" %}
      {% component "power-kill" %}
    </div>
    {% endif %}
  </div>
  <div class="tcs-svh__conns">
    <div class="tcs-svh__conn tcs-svh__conn--join">
      <span class="tcs-svh__connlabel">{% t 'Global.Hostname', 'Hostname' %}</span>
      {% component "service-host-address" %}
      {% comment %} The blueprint's click-to-connect link. Sandboxed, the sanitizer strips any scheme'd href, so no dead button. {% endcomment %}
      {% if TrustedTemplate and Service.ConnectUrl and Service.ConnectUrl != '' %}{% assign connScheme = Service.ConnectUrl | slice: 0, 4 | downcase %}<a class="tcs-svh__join" href="{{ Service.ConnectUrl }}"{% if connScheme == 'http' %} target="_blank" rel="noopener"{% endif %} aria-label="{% t 'ServiceHome.Connect', 'Connect' %}" title="{% t 'ServiceHome.Connect', 'Connect' %}"><i class="fa-solid fa-plug" aria-hidden="true"></i></a>{% endif %}
    </div>
    {% if Service.Image and Service.Image != '' %}
    <div class="tcs-svh__conn tcs-svh__conn--static tcs-svh__conn--image">
      <span class="tcs-svh__connlabel">{% t 'Global.Image', 'Image' %}</span>
      <span class="tcs-svh__connval">{{ Service.Image }}{% if Service.Tag and Service.Tag != '' %}:{{ Service.Tag }}{% endif %}</span>
    </div>
    {% endif %}
    {% if Service.Ports.size > 0 %}
    <div class="tcs-svh__conn tcs-svh__conn--static tcs-svh__conn--ports">
      <span class="tcs-svh__connlabel">{% t 'Global.Ports', 'Ports' %}</span>
      <span class="tcs-svh__portlist">
        {% for p in Service.Ports limit: 4 %}{% if p.Uri and p.Uri != '' %}<a class="tcs-svh__port" href="{{ p.Uri }}" target="_blank" rel="noopener" title="{{ p.Name }}">{{ p.Port }}<i class="fa-solid fa-arrow-up-right-from-square" aria-hidden="true"></i></a>{% else %}<span class="tcs-svh__port" title="{{ p.Name }}">{{ p.Port }}</span>{% endif %}{% endfor %}
        {% if Service.Ports.size > 4 %}<span class="tcs-svh__port tcs-svh__port--more">+{{ Service.Ports.size | minus: 4 }}</span>{% endif %}
      </span>
    </div>
    {% endif %}
  </div>
</header>

contents.css:
/* =====================================================================
   TCADMIN — Total Control · service header, shared by GameService.Header and DockerService.Header
   (build.py inlines this partial into both: a per-surface sheet only applies while its surface renders).
   Renders on EVERY page of the service, so it is compact by default; Home makes it taller.
   ===================================================================== */

/* Service state → one colour lever, read by the rail, pill, orb and art. Defined here (and in the
   home sheets) because html[data-tca-status] is stamped by the engine on every service page. */
html { --tca-svc-state: var(--tca-text-faint); }
html[data-tca-status="started"] { --tca-svc-state: var(--tca-online); }
html[data-tca-status="stopped"] { --tca-svc-state: var(--tca-offline); }
html[data-tca-status="starting"], html[data-tca-status="stopping"] { --tca-svc-state: var(--tca-starting); }

/* The art moves into the band, so the layout's full-page art backdrop stands down while it renders. */
.mud-container:has(> .tcs-svh) > .img-bg { display: none; }

.tcs-svh {
    --cut: var(--tca-cut-lg);
    position: relative; isolation: isolate; overflow: hidden;
    margin: 0 0 18px;
    border: 1px solid var(--tca-line);
    background:
        linear-gradient(90deg, var(--tca-surface) 0%, color-mix(in srgb, var(--tca-surface) 92%, transparent) 38%, color-mix(in srgb, var(--tca-surface) 35%, transparent) 100%);
    box-shadow: var(--tca-shadow-card);
    clip-path: polygon(var(--cut) 0, 100% 0, 100% calc(100% - var(--cut)), calc(100% - var(--cut)) 100%, 0 100%, 0 var(--cut));
    animation: tcs-rise 0.3s var(--tca-ease) both;
}
/* Blueprint grid + accent glow over the art, under the content. */
.tcs-svh::before {
    content: ''; position: absolute; inset: 0; z-index: -1; pointer-events: none;
    background-image:
        radial-gradient(60% 140% at 0% 0%, color-mix(in srgb, var(--tca-accent) 14%, transparent), transparent 70%),
        linear-gradient(to right, var(--tca-grid-line) 1px, transparent 1px),
        linear-gradient(to bottom, var(--tca-grid-line) 1px, transparent 1px);
    background-size: auto, 32px 32px, 32px 32px;
}
/* The cut corners' diagonal border, redrawn (bottom-right; top-left is the rail's). */
.tcs-svh::after {
    content: ''; position: absolute; right: -1px; bottom: -1px; z-index: 4; pointer-events: none;
    width: var(--cut); height: var(--cut);
    background: linear-gradient(to bottom right, transparent calc(50% - 0.8px), var(--tca-line) calc(50% - 0.8px), var(--tca-line) calc(50% + 0.8px), transparent calc(50% + 0.8px));
}

/* Art: right-anchored, fading into the navy toward the identity block. */
.tcs-svh__art {
    position: absolute; z-index: -2; top: 0; right: 0; bottom: 0;
    width: min(70%, 980px); height: 100%; object-fit: cover; object-position: center 30%;
    -webkit-mask-image: linear-gradient(90deg, transparent 0%, #000 55%);
    mask-image: linear-gradient(90deg, transparent 0%, #000 55%);
    opacity: 0.7;
    transition: opacity 0.6s var(--tca-ease), filter 0.6s var(--tca-ease);
}
:root:has(.mud-layout.light-mode) .tcs-svh__art { opacity: 0.32; }
html[data-tca-status="stopped"] .tcs-svh__art { filter: grayscale(0.85); opacity: 0.4; }
:root:has(.mud-layout.light-mode)[data-tca-status="stopped"] .tcs-svh__art { opacity: 0.2; }

/* State rail: a status-coloured top edge that fades out, plus the cut's diagonal in the same colour. */
.tcs-svh__rail {
    position: absolute; inset: 0 0 auto 0; height: 2px; z-index: 3; pointer-events: none;
    background: linear-gradient(90deg, var(--tca-svc-state), color-mix(in srgb, var(--tca-svc-state) 30%, transparent) 40%, transparent 75%);
    transition: background 0.4s;
}
.tcs-svh__rail::before {
    content: ''; position: absolute; top: -1px; left: -1px; width: var(--tca-cut-lg); height: var(--tca-cut-lg);
    background: linear-gradient(to bottom right, transparent calc(50% - 1px), var(--tca-svc-state) calc(50% - 1px), var(--tca-svc-state) calc(50% + 1px), transparent calc(50% + 1px));
}

.tcs-svh__main {
    display: flex; align-items: center; gap: 20px;
    padding: 16px 22px 14px 22px;
    min-width: 0;
}
.tcs-svh__id { display: flex; align-items: center; gap: 16px; flex: 1 1 auto; min-width: 0; }

/* Icon chip: a small cut-corner plate. */
.tcs-svh__icon {
    --c: var(--tca-cut-sm);
    flex: none; width: 48px; height: 48px;
    display: grid; place-items: center;
    color: var(--tca-accent);
    background: color-mix(in srgb, var(--tca-bg-deep) 70%, transparent);
    border: 1px solid color-mix(in srgb, var(--tca-accent) 40%, var(--tca-line));
    clip-path: polygon(var(--c) 0, 100% 0, 100% calc(100% - var(--c)), calc(100% - var(--c)) 100%, 0 100%, 0 var(--c));
    backdrop-filter: blur(6px);
}
.tcs-svh__icon .tca-service-icon { display: grid; place-items: center; line-height: 1; font-size: 1.35rem; }
.tcs-svh__icon .tca-service-icon svg, .tcs-svh__icon .mud-icon-root { width: 26px; height: 26px; font-size: 26px; }

.tcs-svh__stack { display: flex; flex-direction: column; gap: 5px; min-width: 0; }
.tcs-svh__kicker { display: flex; align-items: center; gap: 12px; min-width: 0; flex-wrap: wrap; row-gap: 4px; }

/* Live status pill: orb (LED) + localized status text, outlined in the state colour. */
.tcs-svh__state {
    display: inline-flex; align-items: center; gap: 7px; flex: none;
    height: 22px; padding: 0 9px 0 8px;
    font-family: var(--tca-font-mono); font-size: 0.6875rem; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase;
    color: var(--tca-svc-state);
    border: 1px solid color-mix(in srgb, var(--tca-svc-state) 50%, transparent);
    background: color-mix(in srgb, var(--tca-svc-state) 12%, color-mix(in srgb, var(--tca-bg-deep) 60%, transparent));
    border-radius: var(--tca-r);
    transition: color 0.3s, border-color 0.3s, background-color 0.3s;
}
:root:has(.mud-layout.light-mode) .tcs-svh__state {
    color: color-mix(in srgb, var(--tca-svc-state) 82%, var(--tca-text));
    background: color-mix(in srgb, var(--tca-svc-state) 10%, var(--tca-surface));
}
:root:has(.mud-layout.light-mode) .tcs-svh__name .tca-live-name { text-shadow: 0 1px 10px rgb(255 255 255 / 0.6); }
.tcs-svh__state .tca-live-status-orb {
    width: 7px; height: 7px; border-radius: 50%; flex: none; display: inline-block;
    background: var(--tca-svc-state);
}
.tcs-svh__state .tca-live-status-orb[data-status="started"] {
    box-shadow: 0 0 8px color-mix(in srgb, var(--tca-online) 70%, transparent);
    animation: tcs-pulse 2s ease-in-out infinite;
}
.tcs-svh__state .tca-live-status-orb[data-status="starting"],
.tcs-svh__state .tca-live-status-orb[data-status="stopping"] { animation: tcs-pulse 0.9s ease-in-out infinite; }

.tcs-svh__meta {
    display: inline-flex; align-items: center; gap: 0; min-width: 0;
    font-family: var(--tca-font-mono); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase;
    color: var(--tca-text-dim); white-space: nowrap; overflow: hidden;
}
.tcs-svh__meta > span { overflow: hidden; text-overflow: ellipsis; }
.tcs-svh__meta > span + span::before { content: '//'; margin: 0 9px; color: var(--tca-text-faint); }
.tcs-svh__bp { color: var(--tca-accent); font-weight: 600; }
.tcs-svh__loc i { margin-right: 6px; font-size: 0.625rem; color: var(--tca-text-faint); }

.tcs-svh__name { margin: 0; min-width: 0; line-height: 0.95; }
.tcs-svh__name .tca-live-name {
    display: block;
    font-family: var(--tca-font-display); font-weight: 800; text-transform: uppercase; letter-spacing: 0.005em;
    font-size: clamp(1.5rem, 2.3vw, 2.125rem); line-height: 0.95;
    color: var(--tca-text); text-shadow: 0 2px 14px rgb(3 12 29 / 0.55), var(--tca-glow-text);
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}

/* ---- Power buttons: the atoms are bare <button>s, so the site's CTA styling goes on as-is. ---- */
.tcs-svh__power { display: flex; align-items: center; gap: 10px; flex: none; margin-left: auto; }
.tcs-svh .tca-power,
.tcs-svx .tca-power {
    --cut: var(--tca-cut);
    --edge: var(--tca-line);
    position: relative; isolation: isolate; overflow: hidden;
    display: inline-flex; align-items: center; justify-content: center; gap: 9px;
    min-height: 42px; padding: 0 20px;
    font-family: var(--tca-font-display); font-size: 1rem; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; line-height: 1;
    color: var(--tca-text);
    background: color-mix(in srgb, var(--tca-surface) 60%, transparent);
    border: 1px solid var(--edge); border-radius: 0;
    clip-path: polygon(var(--cut) 0, 100% 0, 100% calc(100% - var(--cut)), calc(100% - var(--cut)) 100%, 0 100%, 0 var(--cut));
    cursor: pointer;
    backdrop-filter: blur(8px);
    transition: background-color var(--tca-fast), border-color var(--tca-fast), color var(--tca-fast), filter var(--tca-fast), transform 0.1s;
}
.tcs-svh .tca-power::before, .tcs-svh .tca-power::after,
.tcs-svx .tca-power::before, .tcs-svx .tca-power::after {
    content: ''; position: absolute; width: var(--cut); height: var(--cut); pointer-events: none;
    background: linear-gradient(to bottom right, transparent calc(50% - 0.8px), var(--edge) calc(50% - 0.8px), var(--edge) calc(50% + 0.8px), transparent calc(50% + 0.8px));
    transition: background var(--tca-fast);
}
.tcs-svh .tca-power::before, .tcs-svx .tca-power::before { top: -1px; left: -1px; }
.tcs-svh .tca-power::after, .tcs-svx .tca-power::after { bottom: -1px; right: -1px; }
.tcs-svh .tca-power:active, .tcs-svx .tca-power:active { transform: translateY(1px); }
.tcs-svh .tca-power:disabled, .tcs-svx .tca-power:disabled { opacity: 0.5; cursor: progress; }
.tcs-svh .tca-power__icon, .tcs-svx .tca-power__icon { font-size: 0.8125rem; }

/* Start = the site's primary CTA: accent fill, accent-hot + glow + light sweep on hover. */
.tcs-svh .tca-power-start, .tcs-svx .tca-power-start {
    --edge: transparent;
    color: var(--tca-accent-ink); background-color: var(--tca-accent); border-color: transparent;
    background-image: linear-gradient(105deg, transparent 35%, rgb(255 255 255 / 0.45) 50%, transparent 65%);
    background-size: 250% 100%; background-position: 160% 0; background-repeat: no-repeat;
}
.tcs-svh .tca-power-start:hover:not(:disabled), .tcs-svx .tca-power-start:hover:not(:disabled) {
    background-color: var(--tca-accent-hot);
    filter: drop-shadow(0 0 14px color-mix(in srgb, var(--tca-accent) 70%, transparent));
    background-position: -60% 0;
    transition: background-color var(--tca-fast), filter var(--tca-fast), background-position 0.6s ease;
}
/* Restart = ghost. */
.tcs-svh .tca-power-restart:hover:not(:disabled), .tcs-svx .tca-power-restart:hover:not(:disabled) { --edge: var(--tca-accent); border-color: var(--tca-accent); }
.tcs-svh .tca-power-restart:hover .tca-power__icon { color: var(--tca-accent); }
/* Stop / Kill = danger outline. */
.tcs-svh .tca-power-stop, .tcs-svh .tca-power-kill,
.tcs-svx .tca-power-stop, .tcs-svx .tca-power-kill {
    --edge: color-mix(in srgb, var(--tca-offline) 60%, transparent);
    color: var(--tca-offline); border-color: var(--edge);
    background-color: color-mix(in srgb, var(--tca-offline) 6%, color-mix(in srgb, var(--tca-surface) 60%, transparent));
}
.tcs-svh .tca-power-stop:hover:not(:disabled), .tcs-svh .tca-power-kill:hover:not(:disabled),
.tcs-svx .tca-power-stop:hover:not(:disabled), .tcs-svx .tca-power-kill:hover:not(:disabled) {
    --edge: var(--tca-offline);
    background-color: color-mix(in srgb, var(--tca-offline) 16%, transparent);
}
.tcs-svh .tca-power-kill, .tcs-svx .tca-power-kill { color: var(--tca-text); background-color: color-mix(in srgb, var(--tca-offline) 22%, transparent); }

/* ---- Connection chips: a HUD footer strip along the band's bottom edge. ---- */
.tcs-svh__conns {
    display: flex; align-items: stretch; gap: 0; min-width: 0;
    border-top: 1px solid color-mix(in srgb, var(--tca-line) 70%, transparent);
    background: color-mix(in srgb, var(--tca-bg-deep) 55%, transparent);
    backdrop-filter: blur(6px);
    padding: 0 8px 0 12px;
}
:root:has(.mud-layout.light-mode) .tcs-svh__conns { background: color-mix(in srgb, var(--tca-bg-deep) 70%, transparent); }
.tcs-svh__conn {
    display: inline-flex; align-items: center; gap: 10px; min-width: 0;
    padding: 5px 14px 5px 10px;
}
.tcs-svh__conn + .tcs-svh__conn { border-left: 1px solid var(--tca-line-soft); }
.tcs-svh__conn--opt { display: none; }
.tcs-svh__conn--opt:has([data-part="value"]) { display: inline-flex; }
/* No address yet (entity loading) → no labelled empty chip. Static (Liquid) chips always show. */
.tcs-svh__conn:not(.tcs-svh__conn--static):not(:has([data-part="value"])) { display: none; }
.tcs-svh__connval { font-family: var(--tca-font-mono); font-size: 0.75rem; letter-spacing: 0.02em; color: var(--tca-text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
.tcs-svh__portlist { display: inline-flex; align-items: center; gap: 6px; flex-wrap: nowrap; }
.tcs-svh__port {
    display: inline-flex; align-items: center; gap: 5px;
    font-family: var(--tca-font-mono); font-size: 0.71875rem; font-weight: 600; color: var(--tca-accent);
    padding: 1px 7px; border-radius: var(--tca-r); text-decoration: none;
    border: 1px solid color-mix(in srgb, var(--tca-accent) 40%, transparent);
    background: color-mix(in srgb, var(--tca-accent) 8%, transparent);
    transition: border-color var(--tca-fast), background-color var(--tca-fast);
}
.tcs-svh__port i { font-size: 0.5625rem; opacity: 0.8; }
a.tcs-svh__port:hover { border-color: var(--tca-accent); background: color-mix(in srgb, var(--tca-accent) 16%, transparent); }
.tcs-svh__port--more { color: var(--tca-text-dim); border-color: var(--tca-line); background: transparent; }

/* No art: the service icon, huge and faint, anchors the band's right side instead. */
.tcs-svh__mark {
    position: absolute; z-index: -1; right: 4%; top: 50%; transform: translateY(-50%) rotate(-8deg);
    color: var(--tca-accent); opacity: 0.07; pointer-events: none; line-height: 1;
}
.tcs-svh__mark .tca-service-icon, .tcs-svh__mark .tca-service-icon * { font-size: 180px !important; width: 180px !important; height: 180px !important; }
.tcs-svh__connlabel {
    font-family: var(--tca-font-mono); font-size: 0.625rem; font-weight: 600; letter-spacing: 0.12em; text-transform: uppercase;
    color: var(--tca-text-faint); flex: none;
}
.tcs-svh__conn--join .tcs-svh__connlabel { color: var(--tca-accent); }
.tcs-svh .tca-conn {
    display: inline-flex; align-items: center; gap: 2px; white-space: nowrap; min-width: 0;
    font-family: var(--tca-font-mono); font-size: 0.75rem; letter-spacing: 0.02em; color: var(--tca-text);
}
.tcs-svh .tca-conn [data-kind="copy"] { padding: 4px; margin-left: 2px; color: var(--tca-text-faint); border-radius: var(--tca-r); }
.tcs-svh .tca-conn [data-kind="copy"]:hover { color: var(--tca-accent); background: color-mix(in srgb, var(--tca-accent) 12%, transparent); }
.tcs-svh .tca-conn [data-kind="copy"] svg { width: 15px; height: 15px; font-size: 15px; }
/* Click-to-connect: the primary CTA's cut plate shrunk to the copy button's height, so the strip keeps its height. */
.tcs-svh__join {
    --c: 6px;
    flex: none; display: inline-grid; place-items: center; margin-left: auto;
    height: 24px; min-width: 34px; padding: 0 10px;
    font-size: 0.75rem; color: var(--tca-accent-ink); background-color: var(--tca-accent); text-decoration: none;
    clip-path: polygon(var(--c) 0, 100% 0, 100% calc(100% - var(--c)), calc(100% - var(--c)) 100%, 0 100%, 0 var(--c));
    transition: background-color var(--tca-fast), opacity var(--tca-fast), filter var(--tca-fast);
}
.tcs-svh__join:hover { background-color: var(--tca-accent-hot); }
/* Inset outline: the clip-path would cut an outer one off. */
.tcs-svh__join:focus-visible { outline: 2px solid var(--tca-accent-ink); outline-offset: -4px; }
/* Live gate off the state bridge: joining anything but a running server just times out. */
html:not([data-tca-status="started"]) .tcs-svh__join { pointer-events: none; opacity: 0.4; filter: grayscale(1); }

/* Home: the band opens up into a real hero. Inner pages keep the compact strip. */
.mud-container:has(.tcs-svx) .tcs-svh__main { padding: 30px 26px 24px; }
.mud-container:has(.tcs-svx) .tcs-svh__name .tca-live-name { font-size: clamp(1.75rem, 3.2vw, 2.875rem); }
.mud-container:has(.tcs-svx) .tcs-svh__icon { width: 56px; height: 56px; }

/* ---- Tablet / phone ---- */
@media (max-width: 959.98px) {
    .tcs-svh__main { padding: 14px 16px 12px; gap: 14px; }
    .mud-container:has(.tcs-svx) .tcs-svh__main { padding: 20px 16px 16px; }
    .tcs-svh__icon, .mud-container:has(.tcs-svx) .tcs-svh__icon { width: 42px; height: 42px; }
    .tcs-svh__art { width: 100%; -webkit-mask-image: linear-gradient(90deg, transparent 0%, #000 80%); mask-image: linear-gradient(90deg, transparent 0%, #000 80%); opacity: 0.45; }
    .tcs-svh__conn--rcon, .tcs-svh__conn--opt:has([data-part="value"]), .tcs-svh__conn--image { display: none; }
    .tcs-svh__conns { padding: 0 4px; }
}
@media (max-width: 599.98px) {
    .tcs-svh { margin-bottom: 12px; }
    .tcs-svh__main { flex-wrap: wrap; row-gap: 12px; }
    .tcs-svh__id { flex: 1 1 100%; gap: 12px; }
    .tcs-svh__icon, .mud-container:has(.tcs-svx) .tcs-svh__icon { width: 38px; height: 38px; }
    .tcs-svh__name .tca-live-name, .mud-container:has(.tcs-svx) .tcs-svh__name .tca-live-name { font-size: 1.5rem; }
    .tcs-svh__loc { display: none; }
    .tcs-svh__power { flex: 1 1 100%; margin-left: 0; }
    .tcs-svh .tca-power { flex: 1 1 0; min-height: 40px; padding: 0 12px; }
    .tcs-svh__conn { flex: 1 1 auto; justify-content: space-between; }
    .tcs-svh__conn--ports { display: none; }
    .tcs-svh__mark { right: -20px; }
}

/* =====================================================================
   TCADMIN — Total Control · service home, shared by GameService.Home and DockerService.Home
   (stats band, deck, side cards, kept-token skins). build.py inlines this partial into both.
   ===================================================================== */

/* ---------------- shared: state lever (same as the header sheets) ---------------- */
html { --tca-svc-state: var(--tca-text-faint); }
html[data-tca-status="started"] { --tca-svc-state: var(--tca-online); }
html[data-tca-status="stopped"] { --tca-svc-state: var(--tca-offline); }
html[data-tca-status="starting"], html[data-tca-status="stopping"] { --tca-svc-state: var(--tca-starting); }

.tcs-svx {
    --tca-stage-h: 560px;
    display: flex; flex-direction: column; gap: 18px; min-width: 0;
    animation: tcs-rise 0.35s var(--tca-ease) both;
}
.tcs-svx__alert:empty { display: none; }

/* ---------------- shared: stats band (site StatsBand) ---------------- */
.tcs-stats {
    --cut: var(--tca-cut-lg);
    position: relative;
    display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    border: 1px solid var(--tca-line-soft);
    background: color-mix(in srgb, var(--tca-surface) 72%, transparent);
    backdrop-filter: blur(8px);
    box-shadow: var(--tca-shadow-card);
    clip-path: polygon(var(--cut) 0, 100% 0, 100% calc(100% - var(--cut)), calc(100% - var(--cut)) 100%, 0 100%, 0 var(--cut));
}
.tcs-stats::before, .tcs-stats::after {
    content: ''; position: absolute; z-index: 3; pointer-events: none; width: var(--cut); height: var(--cut);
    background: linear-gradient(to bottom right, transparent calc(50% - 0.8px), var(--tca-line-soft) calc(50% - 0.8px), var(--tca-line-soft) calc(50% + 0.8px), transparent calc(50% + 0.8px));
}
.tcs-stats::before { top: -1px; left: -1px; }
.tcs-stats::after { bottom: -1px; right: -1px; }

.tcs-stat {
    --tca-pct: 0;
    --tca-bar: var(--tca-accent);
    position: relative; display: flex; flex-direction: column; justify-content: flex-end; gap: 10px;
    min-width: 0; padding: 20px 22px 18px;
}
.tcs-stat + .tcs-stat { border-left: 1px solid var(--tca-line-soft); }
/* A token gated away renders nothing — drop the whole tile rather than a labelled blank. */
.tcs-stat:not(.tcs-stat--image):not(:has(.tca-live)) { display: none; }

.tcs-stat__num {
    display: flex; align-items: baseline; gap: 2px; min-width: 0;
    font-family: var(--tca-font-display); font-weight: 800; line-height: 1;
    font-size: clamp(1.75rem, 2.3vw, 2.375rem); font-variant-numeric: tabular-nums;
    color: var(--tca-text); white-space: nowrap;
}
.tcs-stat__num { flex-wrap: wrap; row-gap: 2px; }
.tcs-stat__den {
    font-family: var(--tca-font-display); font-weight: 600; font-size: 0.5em; letter-spacing: 0.02em;
    color: var(--tca-text-faint); margin-left: 3px; white-space: nowrap;
}
.tcs-stat__den .tca-live { font: inherit; color: inherit; }
.tcs-stat__num--pair { flex-direction: column; align-items: flex-start; gap: 4px; font-size: clamp(1.125rem, 1.4vw, 1.375rem); font-weight: 700; }
.tcs-stat__num--pair > span { display: inline-flex; align-items: baseline; gap: 8px; }
.tcs-stat__num--pair i { font-size: 0.6em; color: var(--tca-accent); }

.tcs-stat__label {
    display: inline-flex; align-items: center; gap: 8px; min-width: 0;
    font-family: var(--tca-font-mono); font-size: 0.6875rem; font-weight: 500; letter-spacing: 0.1em; text-transform: uppercase;
    color: var(--tca-text-dim); white-space: nowrap;
}
.tcs-stat__label i { font-size: 0.75rem; color: var(--tca-text-faint); width: 14px; text-align: center; }

/* Thin --pct bar. A wrapper can't read a child span's --pct (custom properties only inherit
   down), so the bars read the page-scoped --svc-* the engine publishes on <html>. */
.tcs-stat__bar {
    display: block; height: 3px;
    background-color: color-mix(in srgb, var(--tca-line) 70%, transparent);
    background-image: linear-gradient(90deg, var(--tca-bar) calc(var(--tca-pct) * 1%), transparent 0);
    background-repeat: no-repeat;
    transition: background-image 0.6s var(--tca-ease);
}
.tcs-stat--players { --tca-pct: var(--svc-players, 0); }
.tcs-stat--cpu {
    --tca-pct: var(--svc-cpu, 0);
    --tca-heat: clamp(0%, calc((var(--svc-cpu, 0) - 75) * 4%), 100%);
    --tca-bar: color-mix(in srgb, var(--tca-starting) var(--tca-heat), var(--tca-accent));
}
.tcs-stat--memory {
    --tca-pct: var(--svc-memory, 0);
    --tca-heat: clamp(0%, calc((var(--svc-memory, 0) - 80) * 5%), 100%);
    --tca-bar: color-mix(in srgb, var(--tca-starting) var(--tca-heat), var(--tca-accent));
}
.tcs-stat--disk { --tca-pct: var(--svc-disk, 0); }

/* Lead stat glows like the site's live counter; its orb is the band's LED. */
.tcs-stat--uptime .tcs-stat__num { color: var(--tca-accent); text-shadow: 0 0 28px color-mix(in srgb, var(--tca-accent) 50%, transparent); }
:root:has(.mud-layout.light-mode) .tcs-stat--uptime .tcs-stat__num { text-shadow: none; }
.tcs-stat__label .tca-live-status-orb {
    width: 8px; height: 8px; border-radius: 50%; flex: none; display: inline-block;
    background: var(--tca-svc-state);
}
.tcs-stat__label .tca-live-status-orb[data-status="started"] {
    box-shadow: 0 0 8px color-mix(in srgb, var(--tca-online) 70%, transparent);
    animation: tcs-pulse 2s ease-in-out infinite;
}
/* Stale data should look stale: a stopped service still shows its last-known numbers. */
html[data-tca-status="stopped"] .tcs-stat:not(.tcs-stat--uptime):not(.tcs-stat--disk):not(.tcs-stat--image),
html[data-tca-status="unknown"] .tcs-stat:not(.tcs-stat--uptime):not(.tcs-stat--disk):not(.tcs-stat--image) { opacity: 0.5; filter: saturate(0.2); }
html[data-tca-status="stopped"] .tcs-stat--uptime .tcs-stat__num { color: var(--tca-text-faint); text-shadow: none; }

/* ---------------- shared: main grid ---------------- */
.tcs-svx__main { display: grid; grid-template-columns: minmax(0, 1fr); gap: 18px; align-items: start; }
.tcs-svx__main--side { grid-template-columns: minmax(0, 1fr) minmax(0, 360px); }

/* ---------------- shared: the deck — site Screen window chrome over a fixed-height stage ---------------- */
.tcs-deck {
    --cut: var(--tca-cut-lg);
    position: relative; min-width: 0; overflow: hidden;
    /* The deck's width depends on the drawer (open/mini) as much as the viewport: size its chrome off itself. */
    container: tcs-deck / inline-size;
    background: var(--tca-bg-deep);
    border: 1px solid var(--tca-line);
    box-shadow: 0 40px 90px -40px rgb(0 0 0 / 0.7), 0 0 0 1px rgb(255 255 255 / 0.03) inset;
    clip-path: polygon(var(--cut) 0, 100% 0, 100% calc(100% - var(--cut)), calc(100% - var(--cut)) 100%, 0 100%, 0 var(--cut));
}
:root:has(.mud-layout.light-mode) .tcs-deck { box-shadow: var(--tca-shadow-pop); }
.tcs-deck::before, .tcs-deck::after {
    content: ''; position: absolute; z-index: 6; pointer-events: none; width: var(--cut); height: var(--cut);
    background: linear-gradient(to bottom right, transparent calc(50% - 0.8px), var(--tca-line) calc(50% - 0.8px), var(--tca-line) calc(50% + 0.8px), transparent calc(50% + 0.8px));
}
.tcs-deck::before { top: -1px; left: -1px; }
.tcs-deck::after { bottom: -1px; right: -1px; }
.tcs-deck__tin { position: absolute; opacity: 0; pointer-events: none; width: 1px; height: 1px; }

.tcs-deck__chrome {
    display: flex; align-items: center; gap: 14px; min-width: 0;
    height: 46px; padding: 0 8px 0 18px;
    background: var(--tca-chrome);
    border-bottom: 1px solid var(--tca-line-soft);
}
.tcs-deck__lights { display: flex; gap: 6px; flex: none; }
.tcs-deck__lights i { width: 10px; height: 10px; border-radius: 50%; background: color-mix(in srgb, var(--tca-text-faint) 35%, var(--tca-chrome)); }
/* The first light carries the service state. */
.tcs-deck__lights i:first-child { background: var(--tca-svc-state); box-shadow: 0 0 8px color-mix(in srgb, var(--tca-svc-state) 55%, transparent); transition: background 0.3s; }
.tcs-deck__url {
    flex: 0 1 340px; min-width: 0;
    font-family: var(--tca-font-mono); font-size: 0.71875rem; color: var(--tca-text-faint);
    background: color-mix(in srgb, var(--tca-surface) 70%, var(--tca-chrome));
    border: 1px solid var(--tca-line-soft);
    padding: 3px 12px; border-radius: 4px;
    overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
:root:has(.mud-layout.light-mode) .tcs-deck__url { background: var(--tca-surface); }
.tcs-deck__path { display: none; color: var(--tca-text-dim); }
.tcs-tin--console:checked ~ .tcs-deck__chrome .tcs-deck__path--console,
.tcs-tin--logs:checked ~ .tcs-deck__chrome .tcs-deck__path--logs,
.tcs-tin--exec:checked ~ .tcs-deck__chrome .tcs-deck__path--exec,
.tcs-tin--details:checked ~ .tcs-deck__chrome .tcs-deck__path--details,
.tcs-tin--ports:checked ~ .tcs-deck__chrome .tcs-deck__path--ports,
.tcs-tin--advanced:checked ~ .tcs-deck__chrome .tcs-deck__path--advanced { display: inline; }

/* Tabs never shrink (a clipped tab is unreachable); the URL pill gives way first, then the labels. */
.tcs-deck__tabs { display: flex; align-items: stretch; align-self: stretch; gap: 2px; margin-left: auto; flex: none; }
@container tcs-deck (max-width: 860px) { .tcs-deck__url { display: none; } }
@container tcs-deck (max-width: 640px) {
    .tcs-deck__tab { padding: 0 12px; }
    .tcs-deck__tab span { display: none; }
    .tcs-deck__tab i { font-size: 0.9375rem; }
}
.tcs-deck__tab {
    position: relative; display: inline-flex; align-items: center; gap: 8px;
    padding: 0 14px; cursor: pointer; user-select: none;
    font-family: var(--tca-font-display); font-size: 0.9375rem; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase;
    color: var(--tca-text-dim);
    transition: color var(--tca-fast), background-color var(--tca-fast);
}
.tcs-deck__tab i { font-size: 0.75rem; }
.tcs-deck__tab:hover { color: var(--tca-text); background: color-mix(in srgb, var(--tca-accent) 6%, transparent); }
.tcs-deck__tab::after {
    content: ''; position: absolute; left: 10px; right: 10px; bottom: -1px; height: 2px;
    background: var(--tca-accent); transform: scaleX(0); transition: transform 0.2s var(--tca-ease);
}
.tcs-tin--console:checked ~ .tcs-deck__chrome .tcs-tab--console,
.tcs-tin--logs:checked ~ .tcs-deck__chrome .tcs-tab--logs,
.tcs-tin--exec:checked ~ .tcs-deck__chrome .tcs-tab--exec,
.tcs-tin--details:checked ~ .tcs-deck__chrome .tcs-tab--details,
.tcs-tin--ports:checked ~ .tcs-deck__chrome .tcs-tab--ports,
.tcs-tin--advanced:checked ~ .tcs-deck__chrome .tcs-tab--advanced { color: var(--tca-accent); }
.tcs-tin--console:checked ~ .tcs-deck__chrome .tcs-tab--console::after,
.tcs-tin--logs:checked ~ .tcs-deck__chrome .tcs-tab--logs::after,
.tcs-tin--exec:checked ~ .tcs-deck__chrome .tcs-tab--exec::after,
.tcs-tin--details:checked ~ .tcs-deck__chrome .tcs-tab--details::after,
.tcs-tin--ports:checked ~ .tcs-deck__chrome .tcs-tab--ports::after,
.tcs-tin--advanced:checked ~ .tcs-deck__chrome .tcs-tab--advanced::after { transform: scaleX(1); }
.tcs-deck__tin:focus-visible ~ .tcs-deck__chrome .tcs-deck__tabs { outline: 2px solid var(--tca-accent); outline-offset: -2px; }

/* Stage: fixed height, panes absolutely stacked + visibility-toggled so terminals always measure. */
.tcs-deck__stage { position: relative; height: var(--tca-stage-h); min-width: 0; }
.tcs-deck__pane { position: absolute; inset: 0; visibility: hidden; min-width: 0; overflow: hidden; }
/* Sheet panes (details / ports / advanced) scroll on the surface; terminal panes are edge-to-edge. */
.tcs-deck__pane--sheet { overflow-y: auto; padding: 18px 20px; background: var(--tca-surface); }
.tcs-tin--console:checked ~ .tcs-deck__stage .tcs-deck__pane--console,
.tcs-tin--logs:checked ~ .tcs-deck__stage .tcs-deck__pane--logs,
.tcs-tin--exec:checked ~ .tcs-deck__stage .tcs-deck__pane--exec,
.tcs-tin--details:checked ~ .tcs-deck__stage .tcs-deck__pane--details,
.tcs-tin--ports:checked ~ .tcs-deck__stage .tcs-deck__pane--ports,
.tcs-tin--advanced:checked ~ .tcs-deck__stage .tcs-deck__pane--advanced { visibility: visible; }
.tcs-deck__pane .mud-paper { border-radius: 0 !important; box-shadow: none !important; clip-path: none !important; }
.tcs-deck__pane--sheet .mud-paper { background: transparent !important; border: 0 !important; }
.tcs-deck__pane .mud-paper::before, .tcs-deck__pane .mud-paper::after { content: none !important; }

/* A stopped server's console is a record, not a feed: drained, still legible. */
.tcs-deck__pane--term { transition: filter 0.6s, opacity 0.6s; }
html[data-tca-status="stopped"] .tcs-deck__pane--term { filter: grayscale(1) contrast(0.85); opacity: 0.6; }

/* Call-to-start: shown only while stopped and on the console tab. */
.tcs-deck__halt {
    position: absolute; left: 16px; right: 16px; bottom: 16px; z-index: 5;
    display: none; align-items: center; gap: 16px;
    padding: 12px 12px 12px 18px;
    background: color-mix(in srgb, var(--tca-surface) 88%, transparent);
    border: 1px solid color-mix(in srgb, var(--tca-offline) 45%, var(--tca-line));
    border-left: 3px solid var(--tca-offline);
    backdrop-filter: blur(10px);
    box-shadow: var(--tca-shadow-pop);
    animation: tcs-rise 0.3s var(--tca-ease) both;
}
html[data-tca-status="stopped"] .tcs-tin--console:checked ~ .tcs-deck__stage .tcs-deck__halt,
html[data-tca-status="stopped"] .tcs-tin--logs:checked ~ .tcs-deck__stage .tcs-deck__halt,
html[data-tca-status="stopped"] .tcs-tin--exec:checked ~ .tcs-deck__stage .tcs-deck__halt { display: flex; }
.tcs-deck__halt-text { display: flex; flex-direction: column; gap: 2px; min-width: 0; margin-right: auto; }
.tcs-deck__halt-title { font-family: var(--tca-font-display); font-weight: 800; font-size: 1.25rem; text-transform: uppercase; letter-spacing: 0.02em; line-height: 1.05; color: var(--tca-text); }
/* ---------------- shared: side column (kept tokens with their refresh + more actions) ---------------- */
.tcs-svx__side {
    display: flex; flex-direction: column; gap: 18px; min-width: 0;
    height: calc(var(--tca-stage-h) + 48px);
}
.tcs-side { flex: 1 1 0; min-height: 0; display: flex; flex-direction: column; }
.tcs-side > [data-tca-component] {
    --cut: var(--tca-cut-lg);
    position: relative; display: flex !important; flex-direction: column;
    height: 100% !important; min-height: 0; overflow: hidden;
    background: color-mix(in srgb, var(--tca-surface) 86%, transparent) !important;
    border: 1px solid var(--tca-line-soft) !important; border-radius: 0 !important;
    box-shadow: var(--tca-shadow-card) !important;
    clip-path: polygon(var(--cut) 0, 100% 0, 100% calc(100% - var(--cut)), calc(100% - var(--cut)) 100%, 0 100%, 0 var(--cut));
    backdrop-filter: blur(8px);
}
/* Header row: the token's own grid (refresh · label · More). */
.tcs-side > [data-tca-component] > .mud-grid {
    flex: none; margin: 0 !important; width: 100% !important; align-items: center;
    padding: 4px 6px 4px 8px; min-height: 46px;
    border-bottom: 1px solid var(--tca-line-soft);
    background: linear-gradient(90deg, color-mix(in srgb, var(--tca-accent) 7%, transparent), transparent 60%);
}
.tcs-side > [data-tca-component] > .mud-grid > .mud-grid-item { padding: 0 !important; display: flex; align-items: center; }
.tcs-side > [data-tca-component] > .mud-grid > .mud-grid-item:last-child { direction: ltr !important; justify-content: flex-end; padding-right: 10px !important; }
.tcs-side [data-tca-component] > .mud-grid [data-part="label"] {
    font-family: var(--tca-font-display) !important; font-weight: 700 !important; font-size: 1.0625rem !important;
    text-transform: uppercase; letter-spacing: 0.04em; line-height: 1; color: var(--tca-text);
}
.tcs-side [data-part="action"][data-kind="refresh"] { margin: 0 !important; color: var(--tca-text-faint); }
.tcs-side [data-part="action"][data-kind="refresh"]:hover { color: var(--tca-accent); }
.tcs-side [data-part="action"][data-kind="more"] {
    font-family: var(--tca-font-mono) !important; font-size: 0.6875rem !important; letter-spacing: 0.1em; text-transform: uppercase;
    color: var(--tca-accent) !important; text-decoration: none;
}
.tcs-side [data-part="action"][data-kind="more"]::after { content: ' \2192'; }
.tcs-side [data-part="action"][data-kind="more"]:hover { color: var(--tca-accent-hot) !important; }
/* Body scrolls inside the card instead of a fixed inline height. */
.tcs-side > [data-tca-component] > :not(.mud-grid) { flex: 1 1 auto; min-height: 0; overflow-y: auto; }
.tcs-side [data-part="list"] { max-height: none !important; height: 100%; overflow-y: auto; }
/* Logs list rows. */
.tcs-side--logs [data-part="item"] { border-bottom: 1px solid var(--tca-line-soft); transition: background-color var(--tca-fast); }
.tcs-side--logs [data-part="item"]:hover { background: color-mix(in srgb, var(--tca-accent) 7%, transparent); }
.tcs-side--logs [data-part="media"] { background: color-mix(in srgb, var(--tca-accent) 14%, transparent) !important; color: var(--tca-accent) !important; border-radius: var(--tca-r) !important; width: 34px !important; height: 34px !important; }
.tcs-side--logs [data-part="media"] svg { width: 18px; height: 18px; }
.tcs-side--logs [data-part="value"] { font-family: var(--tca-font-mono) !important; font-size: 0.78125rem !important; color: var(--tca-text); }
.tcs-side--logs [data-part="meta"] { font-family: var(--tca-font-mono) !important; font-size: 0.6875rem !important; color: var(--tca-text-faint); margin-top: 0 !important; white-space: nowrap; }
/* Activity timeline: flat rows, state-coloured dots. */
.tcs-side--activity .mud-timeline { padding: 10px 10px 4px 0 !important; }
.tcs-side--activity [data-part="item"] .mud-alert {
    padding: 6px 10px !important; border-radius: var(--tca-r) !important;
    font-size: 0.8125rem; line-height: 1.35;
    background: color-mix(in srgb, var(--tca-surface-2) 70%, transparent) !important;
    color: var(--tca-text-dim) !important;
    border-left: 2px solid var(--tca-line);
}
.tcs-side--activity [data-part="item"] .mud-alert-text-success, .tcs-side--activity [data-part="item"] .mud-alert.mud-alert-text-success { border-left-color: var(--tca-online); }
.tcs-side--activity [data-part="item"] .mud-alert-text-error { border-left-color: var(--tca-offline); }
.tcs-side--activity [data-part="item"] .mud-alert-text-warning { border-left-color: var(--tca-starting); }
.tcs-side [data-part="empty"] { color: var(--tca-text-faint); height: 100%; }
.tcs-side [data-part="empty"] [data-part="value"] { font-family: var(--tca-font-mono); font-size: 0.75rem; letter-spacing: 0.06em; text-transform: uppercase; }

/* No items -> the template's own empty line (the logs list renders nothing at all when empty). */
.tcs-side { position: relative; }
.tcs-side__empty {
    display: none; position: absolute; left: 0; right: 0; top: 47px; bottom: 0; z-index: 2; pointer-events: none; margin: 0;
    flex-direction: column; align-items: center; justify-content: center; gap: 10px;
    font-family: var(--tca-font-mono); font-size: 0.6875rem; letter-spacing: 0.1em; text-transform: uppercase; color: var(--tca-text-faint);
}
.tcs-side__empty i { font-size: 1.5rem; opacity: 0.6; }
.tcs-side--logs:has(> [data-tca-component] > .mud-grid):not(:has([data-part="item"])) .tcs-side__empty { display: flex; }

/* ---------------- shared: kept-token skins (details, advanced actions) ---------------- */
/* The global component skin plates tables/papers; inside the deck the pane is the plate. */
.tcs-deck__pane [data-tca-component], .tcs-deck__pane .mud-table {
    border: 0 !important; clip-path: none !important; box-shadow: none !important; background: transparent !important; border-radius: 0 !important;
}
.tcs-deck__pane [data-tca-component]::before, .tcs-deck__pane [data-tca-component]::after,
.tcs-deck__pane .mud-table::before, .tcs-deck__pane .mud-table::after { content: none !important; }
.tcs-deck [data-tca-component="service-details"] { height: auto !important; }
.tcs-deck [data-tca-component="service-details"] table { border-collapse: collapse; }
.tcs-deck [data-tca-component="service-details"] [data-part="row"] td,
.tcs-deck [data-tca-component="service-details"] tr td { border-bottom: 1px solid var(--tca-line-soft) !important; padding-top: 11px !important; padding-bottom: 11px !important; }
.tcs-deck [data-tca-component="service-details"] [data-part="icon"] { color: var(--tca-text-faint); width: 20px !important; height: 20px !important; font-size: 20px !important; }
.tcs-deck [data-tca-component="service-details"] [data-part="label"] {
    font-family: var(--tca-font-mono) !important; font-size: 0.6875rem !important; font-weight: 500 !important;
    letter-spacing: 0.1em !important; text-transform: uppercase; color: var(--tca-text-faint) !important;
}
.tcs-deck [data-tca-component="service-details"] [data-part="value"] { color: var(--tca-text); }
.tcs-deck [data-tca-component="service-details"] [data-kind="port"] {
    font-family: var(--tca-font-mono) !important; font-size: 0.75rem !important;
    border-radius: var(--tca-r) !important;
    background: color-mix(in srgb, var(--tca-accent) 10%, transparent) !important;
    color: var(--tca-accent) !important;
    border: 1px solid color-mix(in srgb, var(--tca-accent) 35%, transparent) !important;
}

/* Advanced actions: the table becomes a grid of cut-corner action plates. Never a fixed height -
   custom action scripts carry admin-authored names of any length (extensions playbook section 3). */
.tcs-deck [data-tca-component="service-advanced-actions"] { height: auto !important; }
.tcs-deck [data-tca-component="service-advanced-actions"] .mud-table-container { overflow: visible; }
.tcs-deck [data-tca-component="service-advanced-actions"] table { display: block; width: 100%; }
.tcs-deck [data-tca-component="service-advanced-actions"] [data-part="list"] {
    display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 230px), 1fr)); gap: 12px;
}
.tcs-deck [data-tca-component="service-advanced-actions"] [data-part="list"] > tr,
.tcs-deck [data-tca-component="service-advanced-actions"] [data-part="list"] > tr > td { display: block; height: 100%; padding: 0 !important; border: 0 !important; }
/* Custom action scripts arrive wrapped in an inline tooltip root — make it fill the cell too. */
.tcs-deck [data-tca-component="service-advanced-actions"] [data-part="list"] .mud-tooltip-root { display: block; width: 100%; height: 100%; }
.tcs-deck [data-tca-component="service-advanced-actions"] [data-part="action"] {
    --cut: var(--tca-cut);
    width: 100%; min-height: 58px; height: 100%; padding: 10px 16px !important;
    justify-content: flex-start !important; text-align: left;
    border: 1px solid var(--tca-line) !important; border-radius: 0 !important;
    background-color: color-mix(in srgb, var(--tca-surface-2) 55%, transparent) !important;
    clip-path: polygon(var(--cut) 0, 100% 0, 100% calc(100% - var(--cut)), calc(100% - var(--cut)) 100%, 0 100%, 0 var(--cut)) !important;
    /* The cut's diagonal border, drawn as two corner gradients (Mud's ripple owns ::after). */
    --edge: var(--tca-line);
    background-image:
        linear-gradient(to bottom right, transparent calc(50% - 0.8px), var(--edge) calc(50% - 0.8px), var(--edge) calc(50% + 0.8px), transparent calc(50% + 0.8px)),
        linear-gradient(to bottom right, transparent calc(50% - 0.8px), var(--edge) calc(50% - 0.8px), var(--edge) calc(50% + 0.8px), transparent calc(50% + 0.8px)) !important;
    background-size: var(--cut) var(--cut) !important; background-repeat: no-repeat !important;
    background-position: top left, bottom right !important; background-origin: border-box !important;
    font-family: var(--tca-font-display) !important; font-size: 1rem !important; font-weight: 700 !important; letter-spacing: 0.06em !important; text-transform: uppercase;
    color: var(--tca-text) !important;
    transition: border-color var(--tca-fast), background-color var(--tca-fast), color var(--tca-fast);
}
.tcs-deck [data-tca-component="service-advanced-actions"] [data-part="action"] .mud-button-label { justify-content: flex-start; gap: 4px; }
.tcs-deck [data-tca-component="service-advanced-actions"] [data-part="action"] .mud-button-icon-start { color: var(--tca-accent); margin-right: 10px; }
.tcs-deck [data-tca-component="service-advanced-actions"] [data-part="action"]:hover {
    --edge: var(--tca-accent); border-color: var(--tca-accent) !important; background-color: color-mix(in srgb, var(--tca-accent) 9%, transparent) !important;
}
.tcs-deck [data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="delete"],
.tcs-deck [data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="detach"] {
    --edge: color-mix(in srgb, var(--tca-offline) 45%, transparent);
    color: var(--tca-offline) !important; border-color: var(--edge) !important;
}
.tcs-deck [data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="delete"] .mud-button-icon-start,
.tcs-deck [data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="detach"] .mud-button-icon-start { color: var(--tca-offline); }
.tcs-deck [data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="delete"]:hover,
.tcs-deck [data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="detach"]:hover {
    --edge: var(--tca-offline); border-color: var(--tca-offline) !important; background-color: color-mix(in srgb, var(--tca-offline) 10%, transparent) !important;
}
.tcs-deck [data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="reinstall"] .mud-button-icon-start,
.tcs-deck [data-tca-component="service-advanced-actions"] [data-part="action"][data-kind="repair"] .mud-button-icon-start { color: var(--tca-starting); }

/* ---------------- responsive ---------------- */
@media (max-width: 1279.98px) {
    .tcs-svx__main--side { grid-template-columns: minmax(0, 1fr); }
    .tcs-svx__side { height: auto; display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 320px), 1fr)); }
    .tcs-side { height: 320px; flex: none; }
}
@media (max-width: 959.98px) {
    .tcs-svx { --tca-stage-h: 460px; gap: 14px; }
    .tcs-stats { grid-template-columns: repeat(3, minmax(0, 1fr)); }
    .tcs-stat { padding: 16px 16px 14px; }
    .tcs-stat + .tcs-stat { border-left: 0; }
    .tcs-stat:nth-child(n+2) { border-left: 1px solid var(--tca-line-soft); }
    .tcs-stat:nth-child(3n+1) { border-left: 0; }
    .tcs-stat:nth-child(n+4) { border-top: 1px solid var(--tca-line-soft); }
    /* A short last row: the last tile takes the leftover cells instead of leaving a hole. */
    .tcs-stat:last-child:nth-child(3n+1) { grid-column: 1 / -1; }
    .tcs-stat:last-child:nth-child(3n+2) { grid-column: span 2; }
    .tcs-deck__url { display: none; }
    .tcs-deck__tabs { margin-left: auto; }
}
@media (max-width: 599.98px) {
    .tcs-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .tcs-stat:nth-child(n) { border-left: 0; border-top: 0; }
    .tcs-stat:nth-child(even) { border-left: 1px solid var(--tca-line-soft); }
    .tcs-stat:nth-child(n+3) { border-top: 1px solid var(--tca-line-soft); }
    .tcs-stat:last-child:nth-child(3n+1), .tcs-stat:last-child:nth-child(3n+2) { grid-column: auto; }
    .tcs-stat:last-child:nth-child(odd) { grid-column: 1 / -1; }
    .tcs-stat__num { font-size: 1.625rem; }
    .tcs-deck__chrome { padding: 0 4px 0 12px; gap: 8px; }
    .tcs-deck__tab { padding: 0 12px; }
    .tcs-deck__tab span { display: none; }
    .tcs-deck__tab i { font-size: 0.9375rem; }
    /* Phones: the page scrolls, not a box inside it. Non-terminal panes rejoin the flow; the console
       keeps a fixed 70vh absolute box (xterm renders 0 rows in a 0-height box, and inset:0 would let
       another tab resize a live terminal). */
    .tcs-deck__stage { height: auto; min-height: 220px; }
    .tcs-deck__pane--sheet { position: relative; inset: auto; display: none; overflow: visible; padding: 12px; }
    .tcs-tin--details:checked ~ .tcs-deck__stage .tcs-deck__pane--details,
    .tcs-tin--ports:checked ~ .tcs-deck__stage .tcs-deck__pane--ports,
    .tcs-tin--advanced:checked ~ .tcs-deck__stage .tcs-deck__pane--advanced { display: block; visibility: visible; }
    .tcs-deck__pane--term { position: absolute; top: 0; left: 0; right: 0; bottom: auto; height: 70vh; display: block; overflow: hidden; }
    .tcs-tin--console:checked ~ .tcs-deck__stage,
    .tcs-tin--logs:checked ~ .tcs-deck__stage,
    .tcs-tin--exec:checked ~ .tcs-deck__stage { height: 70vh; }
    .tcs-deck [data-tca-component="service-details"] tr td { display: block; width: auto !important; }
    .tcs-deck [data-tca-component="service-details"] tr td:first-child { border-bottom: 0 !important; padding-bottom: 0 !important; }
    .tcs-deck__halt { left: 10px; right: 10px; bottom: 10px; flex-wrap: wrap; }
    .tcs-deck__halt .tca-power { flex: 1 1 100%; }
    .tcs-side { height: 300px; }
}



/* ==================== DOCKER ONLY ==================== */
/* Mirrors theme.json's palette consoleBackground (dark #020916 / light #071a33) — MudBlazor publishes
   no CSS variable for it, and the docker terminals paint their canvas from it. */
:root { --tca-console-bg: #020916; }
:root:has(.mud-layout.light-mode) { --tca-console-bg: #071a33; }
/* Terminals: the tokens ship an inline 420px height — stretch them to the stage (xterm re-fits). */
.tcs-deck__pane--term > [data-tca-component] {
    height: 100% !important; box-sizing: border-box; padding: 12px 6px 6px 16px;
    /* The xterm canvas colour, so the inset reads as the terminal's own margin in both modes. */
    background-color: var(--tca-console-bg) !important;
    border: 0 !important; box-shadow: none !important; border-radius: 0 !important;
}

/* Image tile: the tag is the number, the image the label. */
.tcs-stat__num--text {
    display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; overflow: hidden;
    font-size: clamp(1.125rem, 1.4vw, 1.5rem); line-height: 1.05; white-space: normal; overflow-wrap: anywhere;
}
.tcs-stat--image .tcs-stat__label { overflow: hidden; text-overflow: ellipsis; display: block; }
.tcs-stat--image .tcs-stat__label i { color: var(--tca-accent); margin-right: 8px; }

/* Ports pane: author grid over Service.Ports. */
.tcs-ports { display: flex; flex-direction: column; gap: 8px; }
.tcs-ports__host {
    display: flex; align-items: center; gap: 14px; flex-wrap: wrap;
    padding: 0 0 14px; margin-bottom: 4px; border-bottom: 1px solid var(--tca-line-soft);
}
.tcs-ports__label, .tcs-ports__head {
    font-family: var(--tca-font-mono); font-size: 0.6875rem; font-weight: 500; letter-spacing: 0.1em; text-transform: uppercase; color: var(--tca-text-faint);
}
.tcs-ports__host .tca-conn { display: inline-flex; align-items: center; gap: 4px; font-family: var(--tca-font-mono); font-size: 0.9375rem; font-weight: 600; color: var(--tca-text); }
.tcs-ports__host .tca-conn [data-kind="copy"] { padding: 4px; color: var(--tca-text-faint); }
.tcs-ports__host .tca-conn [data-kind="copy"]:hover { color: var(--tca-accent); }
.tcs-ports__head, .tcs-ports__row { display: grid; grid-template-columns: 110px minmax(0, 1fr) auto; gap: 16px; align-items: center; }
.tcs-ports__head { padding: 6px 14px 2px; }
.tcs-ports__row {
    padding: 10px 14px; min-height: 52px;
    border: 1px solid var(--tca-line-soft);
    background: color-mix(in srgb, var(--tca-surface-2) 45%, transparent);
    transition: border-color var(--tca-fast);
}
.tcs-ports__row:hover { border-color: var(--tca-line); }
.tcs-ports__num {
    justify-self: start;
    font-family: var(--tca-font-mono); font-size: 0.8125rem; font-weight: 600; color: var(--tca-accent);
    padding: 3px 10px; border-radius: var(--tca-r);
    background: color-mix(in srgb, var(--tca-accent) 10%, transparent);
    border: 1px solid color-mix(in srgb, var(--tca-accent) 35%, transparent);
}
.tcs-ports__note { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.tcs-ports__name { font-weight: 600; color: var(--tca-text); overflow-wrap: anywhere; }
.tcs-ports__desc { font-size: 0.8125rem; color: var(--tca-text-dim); overflow-wrap: anywhere; }
.tcs-ports__open {
    display: inline-flex; align-items: center; gap: 7px;
    font-family: var(--tca-font-display); font-size: 0.875rem; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase;
    color: var(--tca-accent); text-decoration: none; padding: 5px 10px;
    border: 1px solid color-mix(in srgb, var(--tca-accent) 40%, transparent);
    transition: background-color var(--tca-fast), border-color var(--tca-fast);
}
.tcs-ports__open i { font-size: 0.6875rem; }
.tcs-ports__open:hover { border-color: var(--tca-accent); background: color-mix(in srgb, var(--tca-accent) 12%, transparent); }
html[data-tca-status="stopped"] .tcs-ports__open { opacity: 0.4; pointer-events: none; }
.tcs-ports__none { margin: 8px 0 0; font-family: var(--tca-font-mono); font-size: 0.75rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--tca-text-faint); }
@media (max-width: 599.98px) {
    .tcs-ports__head { display: none; }
    .tcs-ports__row { grid-template-columns: auto minmax(0, 1fr); gap: 8px 12px; }
    .tcs-ports__open { grid-column: 1 / -1; justify-self: start; }
}

